def __init__(
    self,
    total_tokens: float | None = None,
    *,
    original: trio.CapacityLimiter | None = None,
) -> None:
    if original is not None:
        self.__original = original
    else:
        assert total_tokens is not None
        self.__original = trio.CapacityLimiter(total_tokens)

